{
  "report": "Visão geral (até 2024-01-02): PETR4 apresenta um viés de alta em curto e médio prazo. O preço está acima das médias móveis (MM20, MM50 e MM200) e as médias curtas estão inclinadas para cima, o que caracteriza alinhamento comprador. Em curto prazo as EMAs (EMA9 acima da EMA21) confirmam a continuidade do impulso. O MACD fez cruzamento positivo e o histograma está em barras verdes crescentes, indicando retomada do momentum comprador. O RSI está em cerca de 68 — força, porém ainda abaixo da zona clássica de sobrecompra (70).",
  "signal": "Alta",
  "support_levels": [
    35.6,
    34.8,
    30.8
  ],
  "resistance_levels": [
    38.8,
    40.0
  ],
  "indicator_readings": [
    {
      "indicator": "MM20",
      "reading": "≈35.6",
      "interpretation": "Preço acima da MM20; média inclinada para cima — suporte de curto prazo ativo."
    },
    {
      "indicator": "MM50",
      "reading": "≈34.8",
      "interpretation": "MM50 ascendente; confirma tendência de médio prazo; próximo suporte relevante."
    },
    {
      "indicator": "MM200",
      "reading": "≈30.8",
      "interpretation": "MM200 em subida — tendência de longo prazo mantém-se positiva; suporte estrutural forte."
    },
    {
      "indicator": "EMA9",
      "reading": "≈36.8",
      "interpretation": "EMA9 acima da EMA21 — sinal de alta de curto prazo, reage rápido ao preço."
    },
    {
      "indicator": "EMA21",
      "reading": "≈36.1",
      "interpretation": "EMA21 ascendente; confirma suporte à continuidade do movimento curto."
    },
    {
      "indicator": "MACD",
      "reading": "MACD > sinal, histograma positivo e crescente",
      "interpretation": "Momentum comprador retomado com cruzamento positivo — confirmação técnica de alta recente."
    },
    {
      "indicator": "Bandas de Bollinger",
      "reading": "Preço tocando banda superior; largura moderada",
      "interpretation": "Expansão após compressão em dez/23 — volatilidade em aumento; possível risco de pullback na resistência."
    },
    {
      "indicator": "RSI14",
      "reading": "≈68",
      "interpretation": "Próximo da zona de sobrecompra, mas ainda abaixo de 70 — força presente com risco de correção."
    },
    {
      "indicator": "Volume",
      "reading": "Aumento moderado, sem picos expressivos",
      "interpretation": "Rompimento/alta recente com confirmação volumétrica fraca a moderada — convicção reduzida."
    }
  ]
}
